begin;
select plan(28);

select has_column('public','sales_tracking_attachments','display_order','Attachments have deterministic display order');
select col_not_null('public','sales_tracking_attachments','display_order','Display order is required');
select has_function('public','prepare_sales_tracking_attachment_upload',array['uuid','uuid','date','uuid','bigint','uuid','text','uuid'],'Upload intent authorization exists');
select has_function('public','finalize_sales_tracking_attachment_v2',array['uuid','uuid','uuid','bigint','uuid','jsonb','uuid'],'Plural finalization exists');
select ok(has_function_privilege('service_role','public.finalize_sales_tracking_attachment_v2(uuid,uuid,uuid,bigint,uuid,jsonb,uuid)','execute'),'Service role can finalize');
select ok(not has_function_privilege('authenticated','public.finalize_sales_tracking_attachment_v2(uuid,uuid,uuid,bigint,uuid,jsonb,uuid)','execute'),'Authenticated clients cannot finalize');
select ok(has_function_privilege('service_role','public.get_managed_sales_tracking_attachments(uuid,uuid,uuid)','execute'),'Service role can load Manager evidence detail');
select ok(not has_function_privilege('authenticated','public.get_managed_sales_tracking_attachments(uuid,uuid,uuid)','execute'),'Authenticated clients cannot load Manager evidence directly');

insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values
 ('00000000-0000-0000-0000-000000000000','1c000000-0000-4000-8000-000000000001','authenticated','authenticated','photo3@example.invalid','{}','{}',now(),now()),
 ('00000000-0000-0000-0000-000000000000','1c000000-0000-4000-8000-000000000002','authenticated','authenticated','photo3-manager@example.invalid','{}','{}',now(),now());
update public.profiles set full_name=case when id='1c000000-0000-4000-8000-000000000001'then'Photo Three Supervisor'else'Photo Three Manager'end,must_change_password=false where id::text like'1c000000-%';
insert into public.organizations(id,name,slug)values('2c000000-0000-4000-8000-000000000001','Photo Three Org','photo-three-org');
insert into public.branches(id,organization_id,name,code,timezone,country_code)
values('3c000000-0000-4000-8000-000000000001','2c000000-0000-4000-8000-000000000001','Photo Three Branch','P3','Asia/Riyadh','SA');
insert into public.branch_memberships(branch_id,user_id,role)values('3c000000-0000-4000-8000-000000000001','1c000000-0000-4000-8000-000000000001','branch_manager');
insert into public.organization_memberships(organization_id,user_id,role)values('2c000000-0000-4000-8000-000000000001','1c000000-0000-4000-8000-000000000002','organization_manager');

select lives_ok(format($$select public.ensure_sales_tracking_draft_report('1c000000-0000-4000-8000-000000000001','3c000000-0000-4000-8000-000000000001','%s')$$,private.phase4a_business_date('Asia/Riyadh')),'Draft report exists');

select lives_ok(format($sql$select public.finalize_sales_tracking_attachment_v2('1c000000-0000-4000-8000-000000000001','3c000000-0000-4000-8000-000000000001','%s',0,'7c000000-0000-4000-8000-000000000001',jsonb_build_object('storage_path','2c000000-0000-4000-8000-000000000001/3c000000-0000-4000-8000-000000000001/sales-tracking/%s/7c000000-0000-4000-8000-000000000001.jpg','original_filename','one.jpg','mime_type','image/jpeg','size_bytes',100),null)$sql$,(select id from public.sales_tracking_reports where branch_id='3c000000-0000-4000-8000-000000000001'),(select id from public.sales_tracking_reports where branch_id='3c000000-0000-4000-8000-000000000001')),'First photo finalizes');
select lives_ok(format($sql$select public.finalize_sales_tracking_attachment_v2('1c000000-0000-4000-8000-000000000001','3c000000-0000-4000-8000-000000000001','%s',0,'7c000000-0000-4000-8000-000000000002',jsonb_build_object('storage_path','2c000000-0000-4000-8000-000000000001/3c000000-0000-4000-8000-000000000001/sales-tracking/%s/7c000000-0000-4000-8000-000000000002.png','original_filename','two.png','mime_type','image/png','size_bytes',200),null)$sql$,(select id from public.sales_tracking_reports where branch_id='3c000000-0000-4000-8000-000000000001'),(select id from public.sales_tracking_reports where branch_id='3c000000-0000-4000-8000-000000000001')),'Second photo finalizes');
select lives_ok(format($sql$select public.finalize_sales_tracking_attachment_v2('1c000000-0000-4000-8000-000000000001','3c000000-0000-4000-8000-000000000001','%s',0,'7c000000-0000-4000-8000-000000000003',jsonb_build_object('storage_path','2c000000-0000-4000-8000-000000000001/3c000000-0000-4000-8000-000000000001/sales-tracking/%s/7c000000-0000-4000-8000-000000000003.webp','original_filename','three.webp','mime_type','image/webp','size_bytes',300),null)$sql$,(select id from public.sales_tracking_reports where branch_id='3c000000-0000-4000-8000-000000000001'),(select id from public.sales_tracking_reports where branch_id='3c000000-0000-4000-8000-000000000001')),'Third photo finalizes');
select is((select count(*)from public.sales_tracking_attachments where deleted_at is null and branch_id='3c000000-0000-4000-8000-000000000001'),3::bigint,'Three photos are active');
select results_eq($$select display_order::integer from public.sales_tracking_attachments where deleted_at is null and branch_id='3c000000-0000-4000-8000-000000000001' order by display_order$$,$$select expected_order from (values(1),(2),(3)) as expected(expected_order)$$,'Positions are deterministic');
select throws_ok(format($sql$select public.finalize_sales_tracking_attachment_v2('1c000000-0000-4000-8000-000000000001','3c000000-0000-4000-8000-000000000001','%s',0,'7c000000-0000-4000-8000-000000000004',jsonb_build_object('storage_path','2c000000-0000-4000-8000-000000000001/3c000000-0000-4000-8000-000000000001/sales-tracking/%s/7c000000-0000-4000-8000-000000000004.jpg','original_filename','four.jpg','mime_type','image/jpeg','size_bytes',400),null)$sql$,(select id from public.sales_tracking_reports where branch_id='3c000000-0000-4000-8000-000000000001'),(select id from public.sales_tracking_reports where branch_id='3c000000-0000-4000-8000-000000000001')),'23505','maximum sales tracking photos reached','Fourth photo is rejected');
select lives_ok(format($sql$select public.finalize_sales_tracking_attachment_v2('1c000000-0000-4000-8000-000000000001','3c000000-0000-4000-8000-000000000001','%s',0,'7c000000-0000-4000-8000-000000000005',jsonb_build_object('storage_path','2c000000-0000-4000-8000-000000000001/3c000000-0000-4000-8000-000000000001/sales-tracking/%s/7c000000-0000-4000-8000-000000000005.jpg','original_filename','replacement.jpg','mime_type','image/jpeg','size_bytes',500),'7c000000-0000-4000-8000-000000000002')$sql$,(select id from public.sales_tracking_reports where branch_id='3c000000-0000-4000-8000-000000000001'),(select id from public.sales_tracking_reports where branch_id='3c000000-0000-4000-8000-000000000001')),'Replacement succeeds at capacity');
select is((select display_order from public.sales_tracking_attachments where id='7c000000-0000-4000-8000-000000000005'),2::smallint,'Replacement retains position');
select is((select count(*)from public.sales_tracking_attachments where deleted_at is null and branch_id='3c000000-0000-4000-8000-000000000001'),3::bigint,'Replacement keeps three active photos');
select is(pg_catalog.jsonb_array_length(public.get_sales_tracking_current_state('1c000000-0000-4000-8000-000000000001','3c000000-0000-4000-8000-000000000001')->'attachments'),3,'Current state returns all photos');
select is((public.get_sales_tracking_current_state('1c000000-0000-4000-8000-000000000001','3c000000-0000-4000-8000-000000000001')->'attachment'->>'id')::uuid,'7c000000-0000-4000-8000-000000000001'::uuid,'Singular compatibility metadata remains first photo');

select lives_ok(format($$select public.save_sales_tracking_draft('1c000000-0000-4000-8000-000000000001','3c000000-0000-4000-8000-000000000001','%s',0,'middle_shift','[{"entry_date":"%s","actual_cash":"10","actual_credit":"0","pos_cash":"10","pos_credit":"0","online_delivery":"0"}]','[{"entry_date":"%s","remaining_cash":"0"}]')$$,private.phase4a_business_date('Asia/Riyadh'),private.phase4a_business_date('Asia/Riyadh'),private.phase4a_business_date('Asia/Riyadh')),'Middle period saves before Manager review');
select lives_ok(format($$select public.save_sales_tracking_draft('1c000000-0000-4000-8000-000000000001','3c000000-0000-4000-8000-000000000001','%s',1,'closing_shift','[{"entry_date":"%s","actual_cash":"0","actual_credit":"0","pos_cash":"0","pos_credit":"0","online_delivery":"0"}]','[{"entry_date":"%s","remaining_cash":"0"}]')$$,private.phase4a_business_date('Asia/Riyadh'),private.phase4a_business_date('Asia/Riyadh'),private.phase4a_business_date('Asia/Riyadh')),'Closing period saves before Manager review');
select lives_ok(format($$select public.submit_sales_tracking('1c000000-0000-4000-8000-000000000001','3c000000-0000-4000-8000-000000000001','%s',2,'5c000000-0000-4000-8000-000000000001',repeat('c',64))$$,private.phase4a_business_date('Asia/Riyadh')),'Photo report submits');
select is(pg_catalog.jsonb_array_length(public.get_managed_sales_tracking_attachments('1c000000-0000-4000-8000-000000000002','2c000000-0000-4000-8000-000000000001',(select id from public.sales_tracking_reports where branch_id='3c000000-0000-4000-8000-000000000001'))->'attachments'),3,'Manager detail returns three photos');
select results_eq($$select (photo->>'display_order')::integer from pg_catalog.jsonb_array_elements(public.get_managed_sales_tracking_attachments('1c000000-0000-4000-8000-000000000002','2c000000-0000-4000-8000-000000000001',(select id from public.sales_tracking_reports where branch_id='3c000000-0000-4000-8000-000000000001'))->'attachments')photo$$,$$select expected_order from(values(1),(2),(3))expected(expected_order)$$,'Manager photos are ordered by display order');
select is((select (row->>'evidence_count')::integer from pg_catalog.jsonb_array_elements(public.list_managed_sales_tracking_reports('1c000000-0000-4000-8000-000000000002','2c000000-0000-4000-8000-000000000001')->'sales_rows')row limit 1),3,'Manager list returns only the photo count');
select ok(not(public.list_managed_sales_tracking_reports('1c000000-0000-4000-8000-000000000002','2c000000-0000-4000-8000-000000000001')::text like'%storage_path%'),'Manager list does not expose storage paths');
select throws_ok($$select public.get_managed_sales_tracking_attachments('1c000000-0000-4000-8000-000000000002','2c000000-0000-4000-8000-000000000099',(select id from public.sales_tracking_reports where branch_id='3c000000-0000-4000-8000-000000000001'))$$,'42501','sales tracking attachment access denied','Cross-organization Manager evidence access is denied');

select * from finish();
rollback;
